float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float bounceHeight(float t) {
    float period = 1.2;
    float tt = fract(t / period);
    return 4.0 * tt * (1.0 - tt);
}

vec2 mapScene(vec3 p, float ballY) {
    vec3 ballCenter = vec3(0.0, ballY, 0.0);
    float dBall = sdSphere(p - ballCenter, 0.5);
    float dFloor = p.y;
    if (dBall < dFloor) {
        return vec2(dBall, 1.0);
    }
    return vec2(dFloor, 0.0);
}

vec3 calcNormal(vec3 p, float ballY) {
    vec2 e = vec2(0.001, 0.0);
    float dx = mapScene(p + e.xyy, ballY).x - mapScene(p - e.xyy, ballY).x;
    float dy = mapScene(p + e.yxy, ballY).x - mapScene(p - e.yxy, ballY).x;
    float dz = mapScene(p + e.yyx, ballY).x - mapScene(p - e.yyx, ballY).x;
    return normalize(vec3(dx, dy, dz));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 ro = vec3(0.0, 1.3, 3.2);
    vec3 target = vec3(0.0, 0.4, 0.0);
    vec3 fwd = normalize(target - ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), fwd));
    vec3 up = cross(fwd, right);
    vec3 rd = normalize(fwd * 1.5 + uv.x * right + uv.y * up);

    float ballY = 0.5 + bounceHeight(iTime) * 1.6;

    float t = 0.0;
    float matId = -1.0;
    vec3 p = ro;
    for (int i = 0; i < 64; i++) {
        p = ro + rd * t;
        vec2 res = mapScene(p, ballY);
        if (res.x < 0.001) {
            matId = res.y;
            break;
        }
        t += res.x;
        if (t > 20.0) break;
    }

    vec3 col = vec3(1.0);

    if (matId >= 0.0 && t < 20.0) {
        vec3 n = calcNormal(p, ballY);
        vec3 lightDir = normalize(vec3(0.5, 0.8, 0.3));
        float diff = max(dot(n, lightDir), 0.0);
        float amb = 0.25;

        if (matId > 0.5) {
            vec3 base = vec3(0.85, 0.12, 0.1);
            vec3 viewDir = normalize(ro - p);
            vec3 h = normalize(lightDir + viewDir);
            float spec = pow(max(dot(n, h), 0.0), 32.0);
            col = base * (amb + diff * 0.8) + vec3(1.0) * spec * 0.5;
        } else {
            float dist = length(p.xz);
            float occ = smoothstep(0.9, 0.0, dist) * clamp(1.0 - (ballY - 0.5) * 0.35, 0.2, 1.0);
            vec3 base = vec3(0.95) * (0.5 + 0.5 * diff);
            base *= (1.0 - 0.5 * occ);
            float fade = clamp(1.0 - dist * 0.08, 0.0, 1.0);
            col = mix(vec3(1.0), base, fade);
        }
    }

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float sdEllipse(vec2 p, vec2 r) {
    return (length(p / r) - 1.0) * min(r.x, r.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float floorY = -0.35;
    float period = 1.1;
    float tt = fract(iTime / period);
    float h = 4.0 * tt * (1.0 - tt);
    float amplitude = 0.55;
    float radius = 0.16;

    float squash = 1.0 - 0.5 * pow(1.0 - h, 4.0);
    float sx = radius * (1.0 + (1.0 - squash) * 0.9);
    float sy = radius * squash;

    vec2 center = vec2(0.0, floorY + sy + h * amplitude);
    vec2 p = uv - center;

    float dBall = sdEllipse(p, vec2(sx, sy));
    float dFloor = uv.y - floorY;

    vec3 white = vec3(0.97);
    vec3 red = vec3(0.85, 0.1, 0.08);

    vec3 col = mix(vec3(0.7, 0.75, 0.8), white, smoothstep(0.02, -0.02, dFloor));

    float shadowW = mix(0.35, 0.15, h);
    float dShadow = length((uv - vec2(0.0, floorY)) / vec2(shadowW, 0.05)) - 1.0;
    float shadowMask = smoothstep(0.0, -0.3, dShadow) * (1.0 - 0.6 * h);
    col = mix(col, col * 0.6, clamp(shadowMask, 0.0, 1.0) * smoothstep(0.02, -0.02, dFloor));

    float ballMask = smoothstep(0.01, -0.01, dBall);
    vec3 shaded = red * (0.6 + 0.4 * clamp(1.0 - length(p) / max(sx, sy), 0.0, 1.0));
    col = mix(col, shaded, ballMask);

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float floorY = -0.3;
    float period = 1.0;
    float tt = fract(iTime / period);
    float h = 4.0 * tt * (1.0 - tt);
    float radius = 0.15;
    vec2 center = vec2(0.0, floorY + radius + h * 0.5);

    vec2 warp = vec2(fbm(uv * 2.0 + iTime * 0.1), fbm(uv * 2.0 - iTime * 0.1 + 5.0));
    vec2 warpedUv = uv + (warp - 0.5) * 0.15;
    float pattern = fbm(warpedUv * 3.0 + vec2(0.0, iTime * 0.05));

    vec3 floorCol = mix(vec3(0.85), vec3(1.0), pattern);
    float floorMask = smoothstep(0.02, -0.02, uv.y - floorY);
    vec3 col = mix(vec3(0.75, 0.8, 0.85), floorCol, floorMask);

    float dBall = length(uv - center) - radius;
    float ballMask = smoothstep(0.01, -0.01, dBall);

    vec2 n2 = (uv - center) / radius;
    float nz = sqrt(max(1.0 - dot(n2, n2), 0.0));
    vec3 normal = normalize(vec3(n2, nz));
    vec3 lightDir = normalize(vec3(0.5, 0.7, 0.6));
    float diff = max(dot(normal, lightDir), 0.0);
    vec3 red = vec3(0.85, 0.1, 0.08) * (0.4 + 0.6 * diff);

    col = mix(col, red, ballMask);

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    float m = hash21(p + 17.13);
    return vec2(n, m);
}

float voronoi(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minDist = 8.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 offset = vec2(float(x), float(y));
            vec2 pt = hash22(ip + offset);
            vec2 diff = offset + pt - fp;
            float d = length(diff);
            minDist = min(minDist, d);
        }
    }
    return minDist;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float floorY = -0.3;
    float period = 1.0;
    float tt = fract(iTime / period);
    float h = 4.0 * tt * (1.0 - tt);
    float radius = 0.15;
    vec2 center = vec2(0.0, floorY + radius + h * 0.5);

    float v = voronoi(uv * 6.0);
    vec3 tileCol = mix(vec3(0.9), vec3(1.0), smoothstep(0.0, 0.4, v));
    float grout = smoothstep(0.03, 0.06, v);
    tileCol *= mix(0.7, 1.0, grout);

    float floorMask = smoothstep(0.02, -0.02, uv.y - floorY);
    vec3 col = mix(vec3(0.7, 0.75, 0.8), tileCol, floorMask);

    float distToCenter = length(uv - vec2(center.x, floorY));
    float shadow = smoothstep(0.35, 0.0, distToCenter) * (1.0 - 0.5 * h);
    col = mix(col, col * 0.65, shadow * floorMask);

    float dBall = length(uv - center) - radius;
    float ballMask = smoothstep(0.01, -0.01, dBall);
    vec2 n2 = (uv - center) / radius;
    float nz = sqrt(max(1.0 - dot(n2, n2), 0.0));
    vec3 normal = normalize(vec3(n2, nz));
    float diff = max(dot(normal, normalize(vec3(0.5, 0.7, 0.6))), 0.0);
    vec3 red = vec3(0.85, 0.1, 0.08) * (0.4 + 0.6 * diff);
    col = mix(col, red, ballMask);

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float floorY = -0.3;
    float period = 1.0;
    float phase = iTime / period;
    float tt = fract(phase);
    float h = 4.0 * tt * (1.0 - tt);
    float radius = 0.16;
    vec2 center = vec2(0.0, floorY + radius + h * 0.55);

    vec3 white = vec3(0.96);
    float floorMask = smoothstep(0.015, -0.015, uv.y - floorY);

    vec2 contact = vec2(0.0, floorY);
    vec2 rel = uv - contact;
    float r = length(rel);
    float ang = atan(rel.y, rel.x);

    float impactTime = tt;
    float ringPhase = r * 18.0 - impactTime * 14.0;
    float rings = 0.5 + 0.5 * sin(ringPhase);
    float ringFade = exp(-r * 3.0) * smoothstep(0.0, 0.15, impactTime) * (1.0 - smoothstep(0.15, 0.6, impactTime));
    float angleMod = 0.9 + 0.1 * sin(ang * 6.0);

    vec3 floorCol = mix(white, white * 0.85, rings * ringFade * angleMod);
    vec3 col = mix(vec3(0.75, 0.8, 0.85), floorCol, floorMask);

    vec2 pRel = uv - center;
    float pr = length(pRel);
    float pa = atan(pRel.y, pRel.x);
    float dBall = pr - radius;
    float ballMask = smoothstep(0.008, -0.008, dBall);

    float rn = clamp(pr / radius, 0.0, 1.0);
    float highlightAngle = pa - 2.4;
    float highlight = exp(-8.0 * (1.0 - rn)) * (0.5 + 0.5 * cos(highlightAngle));
    float shade = mix(0.35, 1.0, (1.0 - rn));
    vec3 red = vec3(0.85, 0.08, 0.06) * shade + vec3(1.0) * highlight * 0.5;

    col = mix(col, red, ballMask);
    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float ballHeight(float t) {
    float period = 1.1;
    float tt = fract(t / period);
    return 4.0 * tt * (1.0 - tt);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float floorY = -0.32;
    float radius = 0.15;

    float floorMask = smoothstep(0.015, -0.015, uv.y - floorY);
    vec3 col = mix(vec3(0.75, 0.8, 0.85), vec3(0.97), floorMask);

    vec3 trailAccum = vec3(0.0);
    float coverage = 0.0;
    const int N = 14;
    for (int i = 0; i < N; i++) {
        float dt = float(i) * 0.025;
        float tPast = iTime - dt;
        float h = ballHeight(tPast);
        vec2 center = vec2(0.0, floorY + radius + h * 0.5);
        float d = length(uv - center) - radius;
        float mask = smoothstep(0.01, -0.01, d);
        float weight = exp(-float(i) * 0.35);
        trailAccum += vec3(0.85, 0.1, 0.08) * mask * weight;
        coverage = max(coverage, mask * weight);
    }

    col = mix(col, clamp(trailAccum, 0.0, 1.0), clamp(coverage, 0.0, 1.0));

    float hNow = ballHeight(iTime);
    vec2 centerNow = vec2(0.0, floorY + radius + hNow * 0.5);
    float dNow = length(uv - centerNow) - radius;
    float maskNow = smoothstep(0.01, -0.01, dNow);
    vec3 shade = vec3(0.9, 0.12, 0.1) * (0.6 + 0.4 * clamp(1.0 - length(uv - centerNow) / radius, 0.0, 1.0));
    col = mix(col, shade, maskNow);

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float sdFlame(vec2 p, float t) {
    float sway = 0.10 * sin(t * 3.0 + p.y * 3.5) + 0.05 * sin(t * 7.0 - p.y * 2.0);
    p.x -= sway * (p.y + 0.5);
    float widthTop = 0.02;
    float widthBot = 0.30;
    float k = clamp((p.y + 0.55) / 1.05, 0.0, 1.0);
    float w = mix(widthBot, widthTop, k) + 0.02 * sin(t * 10.0 + p.y * 8.0) * (1.0 - k);
    w = max(w, 0.02);
    vec2 q = vec2(p.x / w, p.y - 0.05);
    float d = length(q) - 1.0;
    return d * w;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;
    vec2 p = uv;
    p.y += 0.15;

    float d = sdFlame(p, t);
    float core = smoothstep(0.05, -0.05, d);
    float glow = exp(-max(d, 0.0) * 8.0) * 0.5;

    vec3 hot = vec3(1.0, 0.95, 0.6);
    vec3 mid = vec3(1.0, 0.5, 0.05);
    vec3 outerc = vec3(0.6, 0.05, 0.0);

    float innerMix = smoothstep(-0.25, 0.05, d);
    vec3 flameCol = mix(hot, mid, clamp(innerMix * 1.5, 0.0, 1.0));
    flameCol = mix(flameCol, outerc, clamp(innerMix, 0.0, 1.0));

    vec3 col = vec3(0.0);
    col += flameCol * core;
    col += vec3(1.0, 0.4, 0.05) * glow;

    float wick = exp(-length(p - vec2(0.0, -0.35)) * 20.0);
    col += vec3(1.0, 0.6, 0.2) * wick * 0.3;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;
    vec2 p = uv;
    p.y += 0.15;

    float sway = 0.09 * sin(t * 2.2 + p.y * 3.0);
    vec2 pw = p;
    pw.x -= sway * (p.y + 0.5);
    float k = clamp((pw.y + 0.55) / 1.05, 0.0, 1.0);
    float w = mix(0.30, 0.015, k);
    w = max(w, 0.02);
    vec2 q = vec2(pw.x / w, pw.y - 0.05);
    float d = length(q) - 1.0;
    float mask = smoothstep(0.05, -0.05, d);

    vec2 warpP = p * 3.0 + vec2(0.0, -t * 2.0);
    vec2 warp = vec2(fbm(warpP), fbm(warpP + vec2(5.2, 1.3))) - 0.5;
    float n = fbm(p * 4.0 + warp * 1.5 + vec2(0.0, -t * 3.0));

    vec3 hot = vec3(1.0, 0.9, 0.5);
    vec3 mid = vec3(1.0, 0.45, 0.05);
    vec3 outerc = vec3(0.5, 0.02, 0.0);
    vec3 col = mix(outerc, mid, clamp(n * 1.4, 0.0, 1.0));
    col = mix(col, hot, clamp((n - 0.4) * 2.0, 0.0, 1.0) * (1.0 - k));

    vec3 finalCol = col * mask;
    finalCol += vec3(1.0, 0.5, 0.1) * exp(-max(d, 0.0) * 6.0) * 0.35;

    finalCol = clamp(finalCol, 0.0, 1.0);
    fragColor = vec4(finalCol, 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float density(vec3 p, float t) {
    float r = length(p.xz);
    float k = clamp((p.y + 0.5) / 1.1, 0.0, 1.0);
    float w = mix(0.35, 0.02, k);
    float base = 1.0 - smoothstep(w * 0.7, w * 1.2, r);
    base *= smoothstep(-0.6, -0.4, p.y) * smoothstep(0.65, 0.3, p.y);
    float n = noise(p.xz * 4.0 + vec2(0.0, -t * 3.0));
    n += 0.5 * noise(p.xz * 8.0 + vec2(t * 2.0, -t * 5.0));
    return max(base * (0.4 + 0.8 * n) - 0.1, 0.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;
    vec3 ro = vec3(0.0, 0.0, -2.0);
    vec3 rd = normalize(vec3(uv, 1.4));
    vec3 col = vec3(0.0);
    float transmittance = 1.0;
    float zpos = 0.0;
    for (int i = 0; i < 40; i++) {
        vec3 p = ro + rd * zpos;
        float dens = density(p - vec3(0.0, 0.15, 0.0), t);
        vec3 hot = vec3(1.0, 0.85, 0.4);
        vec3 outerc = vec3(0.9, 0.25, 0.02);
        vec3 c = mix(outerc, hot, clamp(dens * 1.5, 0.0, 1.0));
        col += transmittance * dens * c * 0.15;
        transmittance *= exp(-dens * 0.3);
        zpos += 0.06;
        if (transmittance < 0.01) break;
    }
    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;
    vec2 base = vec2(0.0, -0.45);
    vec2 rp = uv - base;
    float ang = atan(rp.x, rp.y);
    float rad = length(rp);

    float k = clamp(rp.y / 1.1, 0.0, 1.0);
    float baseEdge = mix(0.42, 0.02, k);

    float wobble = 0.06 * sin(ang * 3.0 + t * 5.0 + k * 4.0)
                 + 0.035 * sin(ang * 7.0 - t * 9.0)
                 + 0.02 * sin(ang * 13.0 + t * 17.0);

    float edge = max(baseEdge + wobble * (1.0 - k), 0.01);
    float d = rad - edge;
    float core = smoothstep(0.06, -0.04, d);

    float tt = clamp(rad / edge, 0.0, 1.0);
    vec3 hot = vec3(1.0, 0.95, 0.65);
    vec3 mid = vec3(1.0, 0.5, 0.08);
    vec3 outerc = vec3(0.55, 0.04, 0.0);
    vec3 col = mix(hot, mid, clamp(tt * 1.6, 0.0, 1.0));
    col = mix(col, outerc, clamp((tt - 0.5) * 2.0, 0.0, 1.0));

    vec3 finalCol = col * core;
    finalCol += vec3(1.0, 0.45, 0.1) * exp(-max(d, 0.0) * 7.0) * 0.3;
    finalCol = clamp(finalCol, 0.0, 1.0);
    fragColor = vec4(finalCol, 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float layer(vec2 p, float t, float seed) {
    vec2 q = p;
    q.y += t;
    q.x += 0.15 * sin(t * 2.0 + seed * 6.0 + p.y * 3.0);
    float n = noise(q * 3.0 + seed * 10.0);
    n += 0.5 * noise(q * 6.0 + seed * 20.0);
    return n / 1.5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;
    vec2 p = uv;
    p.y += 0.4;

    float k = clamp((p.y + 0.5) / 1.1, 0.0, 1.0);
    float width = mix(0.35, 0.03, k);
    float envelope = 1.0 - smoothstep(width * 0.8, width * 1.3, abs(p.x));
    envelope *= smoothstep(-0.55, -0.35, p.y) * smoothstep(0.7, 0.2, p.y);

    float acc = 0.0;
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        acc += layer(p * (1.0 + 0.1 * fi), -t * (0.6 + 0.15 * fi), fi) * (1.0 / (1.0 + fi * 0.6));
    }
    acc /= 2.2;
    acc *= envelope;

    vec3 hot = vec3(1.0, 0.9, 0.55);
    vec3 mid = vec3(1.0, 0.45, 0.05);
    vec3 outerc = vec3(0.4, 0.02, 0.0);
    vec3 col = mix(outerc, mid, clamp(acc * 1.6, 0.0, 1.0));
    col = mix(col, hot, clamp((acc - 0.45) * 2.2, 0.0, 1.0));
    col *= envelope;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

vec2 hash2(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453);
}

float voronoi(vec2 p, float t) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minD = 1.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 g = vec2(float(x), float(y));
            vec2 o = hash2(ip + g);
            o = 0.5 + 0.5 * sin(t * 2.0 + 6.2831 * o);
            vec2 r = g + o - fp;
            float d = dot(r, r);
            minD = min(minD, d);
        }
    }
    return sqrt(minD);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;
    vec2 p = uv;
    p.y += 0.35;

    float k = clamp((p.y + 0.5) / 1.1, 0.0, 1.0);
    float width = mix(0.4, 0.02, k);
    float sway = 0.08 * sin(t * 2.0 + p.y * 3.0);
    float envelope = 1.0 - smoothstep(width * 0.8, width * 1.3, abs(p.x - sway * (1.0 - k)));
    envelope *= smoothstep(-0.55, -0.35, p.y) * smoothstep(0.75, 0.15, p.y);

    vec2 vp = p * 6.0 + vec2(0.0, -t * 1.5);
    float v = voronoi(vp, t);
    float cell = 1.0 - smoothstep(0.0, 0.5, v);

    vec3 hot = vec3(1.0, 0.9, 0.5);
    vec3 mid = vec3(1.0, 0.45, 0.05);
    vec3 outerc = vec3(0.5, 0.03, 0.0);
    vec3 col = mix(outerc, mid, clamp(cell * 1.4, 0.0, 1.0));
    col = mix(col, hot, clamp((cell - 0.55) * 2.2, 0.0, 1.0));
    col *= envelope;

    vec2 sp = p * 3.0 + vec2(0.0, -t * 0.8);
    float sv = voronoi(sp + 17.0, t * 1.3);
    float spark = smoothstep(0.04, 0.0, sv) * smoothstep(0.9, 0.2, p.y) * step(0.0, p.y);
    col += vec3(1.0, 0.6, 0.2) * spark * 0.6;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

