void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 2.0;
    const float PI = 3.14159265359;
    const float TWO_PI = 6.28318530718;

    float r = length(uv);
    float a = atan(uv.x, uv.y);
    if (a < 0.0) a += TWO_PI;

    float secN = mod(iTime, 60.0);
    float minN = mod(iTime / 60.0, 60.0);
    float hourN = mod(iTime / 3600.0, 12.0);

    float aSec = secN / 60.0 * TWO_PI;
    float aMin = (minN + secN / 60.0) / 60.0 * TWO_PI;
    float aHour = (hourN + minN / 60.0) / 12.0 * TWO_PI;

    vec3 col = vec3(0.02, 0.02, 0.05) + 0.05 * r;

    float faceMask = smoothstep(0.95, 0.9, r);
    col = mix(col, vec3(0.08, 0.08, 0.14), faceMask);

    for (int i = 0; i < 60; i++) {
        float ta = float(i) / 60.0 * TWO_PI;
        float ad = abs(mod(a - ta + PI, TWO_PI) - PI);
        float isMajor = mod(float(i), 5.0) < 0.5 ? 1.0 : 0.0;
        float w = mix(0.006, 0.014, isMajor);
        float radialBand = smoothstep(0.78, 0.83, r) * smoothstep(0.95, 0.9, r);
        float band = smoothstep(w, 0.0, ad) * radialBand;
        col = mix(col, vec3(0.9), band);
    }

    float dSecA = abs(mod(a - aSec + PI, TWO_PI) - PI);
    float secHand = smoothstep(0.05, 0.0, dSecA) * smoothstep(0.82, 0.78, r);
    col = mix(col, vec3(1.0, 0.3, 0.2), secHand);

    float dMinA = abs(mod(a - aMin + PI, TWO_PI) - PI);
    float minHand = smoothstep(0.03, 0.0, dMinA) * smoothstep(0.67, 0.63, r);
    col = mix(col, vec3(0.95), minHand);

    float dHourA = abs(mod(a - aHour + PI, TWO_PI) - PI);
    float hourHand = smoothstep(0.045, 0.0, dHourA) * smoothstep(0.47, 0.43, r);
    col = mix(col, vec3(0.95), hourHand);

    float hub = smoothstep(0.04, 0.03, r);
    col = mix(col, vec3(1.0, 0.3, 0.2), hub);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

mat2 rot(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a)); }

float gThetaSec;
float gThetaMin;
float gThetaHour;

float sdCylinderZ(vec3 p, float r, float h) {
    vec2 d = vec2(length(p.xy) - r, abs(p.z) - h);
    return min(max(d.x, d.y), 0.0) + length(max(d, 0.0));
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float map(vec3 p) {
    float d = sdCylinderZ(p, 1.0, 0.05);

    vec3 ps = p - vec3(0.0, 0.0, 0.05);
    ps.xy = rot(-gThetaSec) * ps.xy;
    float hand = sdBox(ps - vec3(0.0, 0.45, 0.0), vec3(0.012, 0.45, 0.02));
    d = min(d, hand);

    vec3 pm = p - vec3(0.0, 0.0, 0.05);
    pm.xy = rot(-gThetaMin) * pm.xy;
    float mh = sdBox(pm - vec3(0.0, 0.34, 0.0), vec3(0.02, 0.34, 0.02));
    d = min(d, mh);

    vec3 ph = p - vec3(0.0, 0.0, 0.05);
    ph.xy = rot(-gThetaHour) * ph.xy;
    float hh = sdBox(ph - vec3(0.0, 0.24, 0.0), vec3(0.03, 0.24, 0.02));
    d = min(d, hh);

    return d;
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    const float TWO_PI = 6.28318530718;

    float secN = mod(iTime, 60.0);
    float minN = mod(iTime / 60.0, 60.0);
    float hourN = mod(iTime / 3600.0, 12.0);

    gThetaSec = secN / 60.0 * TWO_PI;
    gThetaMin = (minN + secN / 60.0) / 60.0 * TWO_PI;
    gThetaHour = (hourN + minN / 60.0) / 12.0 * TWO_PI;

    vec3 ro = vec3(0.0, 0.0, 2.2);
    vec3 rd = normalize(vec3(uv, -1.6));

    float t = 0.0;
    bool hit = false;
    vec3 p = ro;
    for (int i = 0; i < 64; i++) {
        p = ro + rd * t;
        float d = map(p);
        if (d < 0.001) { hit = true; break; }
        t += d;
        if (t > 6.0) break;
    }

    vec3 col = vec3(0.02, 0.02, 0.05);

    if (hit) {
        vec3 n = getNormal(p);
        vec3 lightDir = normalize(vec3(0.5, 0.6, 1.0));
        float diff = max(dot(n, lightDir), 0.0);
        vec3 base = vec3(0.15, 0.16, 0.22);
        float rXY = length(p.xy);
        if (p.z > 0.06) {
            base = (rXY < 0.06) ? vec3(0.9, 0.3, 0.2) : vec3(0.9);
        }
        col = base * (0.25 + 0.75 * diff);
    }

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float sdSegment(vec2 p, vec2 a, vec2 b) {
