    float minD = 8.0;
    vec2 minC = vec2(0.0);
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 offset = vec2(float(x), float(y));
            vec2 h = hash22(ip + offset);
            vec2 r = offset + h - fp;
            float d = dot(r, r);
